#!/usr/bin/env bash
# Minimal reproduction generated by stutter for Formance Ledger v2.4.18 mutant: idempotency log written in a second transaction after the business commit.
# usage: BASE_URL=http://127.0.0.1:3000 ./repro.sh [faulted|clean]
#   faulted: the delivery order that breaks; clean: the original order.
set -euo pipefail
cd "$(dirname "$0")"
: "${BASE_URL:?set BASE_URL to the running service}"
SECRET=""
send() {
  local f=$1 path=$2 method=${3:-POST} t sig
  local hdr=()
  curl -sS -o /dev/null -w "$f %{http_code}\n" -X "$method" "$BASE_URL$path" -H 'Content-Type: application/json' ${hdr[@]+"${hdr[@]}"} --data-binary @"$f"
}
if [ "${1:-faulted}" = clean ]; then
  send 9.json "/v2/default/transactions" POST
else
  # send, kill the service after its commit 1, restart, resend: needs stutter's wire proxy; curl cannot stop a process at a commit
  send 9.json "/v2/default/transactions" POST
fi
